/* @lc app=leetcode id=1145 lang=kotlin */ class Solution { fun sz(t: TreeNode?): Int = if (t == null) 0 else 1 + sz(t.left) + sz(t.right) fun find(t: TreeNode?, x: Int): TreeNode? = if (t == null || t.`val` == x) t else find(t.left, x) ?: find(t.right, x) fun btreeGameWinningMove(root: TreeNode?, n: Int, x: Int): Boolean = find(root, x)!!.let { listOf(sz(it.left), sz(it.right), n - 1 - sz(it.left) - sz(it.right)).max() > n / 2 } }